<script lang="ts">
    import { onMount } from 'svelte'; import { RefreshCw } from '@lucide/svelte';
    import * as Alert from '$lib/components/ui/alert'; import { Badge } from '$lib/components/ui/badge'; import { Button } from '$lib/components/ui/button'; import * as Card from '$lib/components/ui/card'; import { Input } from '$lib/components/ui/input'; import * as Table from '$lib/components/ui/table';
    import { getAppContext } from './context.svelte'; import { formatBytes } from './format';
    const app=getAppContext(); let query=$state(''); onMount(()=>{if(!app.storage)void app.refreshStorage()}); const datasets=$derived((app.storage?.datasets??[]).filter(d=>!query||d.name.toLowerCase().includes(query.toLowerCase())));
</script>
<section class="space-y-6"><header class="flex items-end justify-between"><div><h2 class="text-3xl font-semibold tracking-tight">데이터셋</h2><p class="mt-1 text-sm text-muted-foreground">ZFS 데이터셋과 zvol의 용량 및 보안 상태입니다.</p></div><Button variant="outline" disabled={app.storageLoading} onclick={()=>app.refreshStorage()}><RefreshCw class={app.storageLoading?'animate-spin':''}/>새로고침</Button></header>{#if app.storageError}<Alert.Root variant="destructive"><Alert.Title>조회 실패</Alert.Title><Alert.Description>{app.storageError}</Alert.Description></Alert.Root>{/if}
<Card.Root><Card.Header class="flex flex-row items-center justify-between gap-4"><div><Card.Title>데이터셋 목록</Card.Title><Card.Description>{app.storage?.datasets?.length??0}개 데이터셋 · {app.storage?.snapshotCount??0}개 스냅샷</Card.Description></div><Input class="max-w-xs" bind:value={query} placeholder="데이터셋 검색" /></Card.Header><Card.Content>{#if !app.storageLoading&&datasets.length===0}<p class="py-12 text-center text-sm text-muted-foreground">{query?'검색 결과가 없습니다.':'표시할 데이터셋이 없습니다.'}</p>{:else}<Table.Root><Table.Header><Table.Row><Table.Head>데이터셋</Table.Head><Table.Head>유형</Table.Head><Table.Head>사용량</Table.Head><Table.Head>가용</Table.Head><Table.Head>보안</Table.Head></Table.Row></Table.Header><Table.Body>{#each datasets as dataset}<Table.Row><Table.Cell><p class="font-medium">{dataset.name}</p><p class="text-xs text-muted-foreground">{dataset.mountpoint||dataset.id}</p></Table.Cell><Table.Cell>{dataset.type||'FILESYSTEM'}</Table.Cell><Table.Cell>{formatBytes(dataset.used)}</Table.Cell><Table.Cell>{formatBytes(dataset.available)}</Table.Cell><Table.Cell><Badge variant="outline">{dataset.locked?'잠김':dataset.encrypted?'암호화':'일반'}</Badge></Table.Cell></Table.Row>{/each}</Table.Body></Table.Root>{/if}</Card.Content></Card.Root></section>
